		expect(wallDurationMs).toBeLessThan(2500);
		evidence.push({ phase: deletion.phase, ...measurement, wallDurationMs });
	}
	expect(
		await db
			.selectFrom("_emdash_media_usage_collection_deletions")
			.select("collection_id")
